class Solution {
    public int mySqrt(int x) {
        if (x < 2) {
            return x;
        }

        int lo = 1;
        int hi = x / 2;
        int answer = 1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (mid <= x / mid) {
                answer = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return answer;
    }
}

class Solution {
    public int mySqrt(int x) {
        if (x < 2) {
            return x;
        }

        long r = x;
        while (r > x / r) {
            r = (r + x / r) / 2;
        }
        return (int) r;
    }
}

class Solution {
    public int mySqrt(int x) {
        long remaining = x;
        long root = 0;
        long bit = 1L << 30;

        while (bit > remaining) {
            bit >>= 2;
        }

        while (bit != 0) {
            if (remaining >= root + bit) {
                remaining -= root + bit;
                root = (root >> 1) + bit;
            } else {
                root >>= 1;
            }
            bit >>= 2;
        }
        return (int) root;
    }
}

class Solution {
    public int mySqrt(int x) {
        long remaining = x;
        long odd = 1;
        int root = 0;
        while (remaining >= odd) {
            remaining -= odd;
            odd += 2;
            root++;
        }
        return root;
    }
}
